  "This request comes from the Bulk Builder (PLAN pass). Read the instruction and the design fields, then LIST the outputs you will produce, LABELS ONLY (no field content). Return ONLY a raw JSON object: {\"translate\": <true ONLY if the instruction asks to translate/localize into languages, else false>, \"labels\": [ ... ]}. When translate is true the labels are the LANGUAGE NAMES (written in the same language the user used). Otherwise the labels are a distinct short topic/seed per output. Honor any quantity named in the instruction; otherwise a sensible set (about 6 to 12). Hard cap 500.\n": "此请求来自 Bulk Builder（PLAN pass）。阅读说明和设计字段，然后列出您将产生的输出，仅标签（无字段内容）。仅返回原始 JSON 对象：{\"translate\": <true ONLY if the instruction asks to translate/localize into languages, else false>, \"labels\": [ ... ]}。当翻译为 true 时，标签是语言名称（以用户使用的相同语言编写）。否则，标签是每个输出的不同的短主题/种子。遵守说明书中指定的任何数量；否则是一个合理的集合（大约 6 到 12）。硬上限 500.\n",
