  "Add products from the panel's Assets > Products section, and they'll appear here automatically.": "从面板的资产 > 产品部分添加产品，它们将自动显示在此处。",
  "A design and video studio that runs on this machine.": "在此计算机上运行的设计和视频工作室。",
  "Your work stays here. Documents, media and version history never leave this computer.": "您的设计成果保留在这里。文档、媒体和版本历史记录永远不会离开这台计算机。",
  "Free to use. Source available under the Business Source License 1.1.": "免费使用。源代码依据 Business Source License 1.1 公开。",
  "Your projects are stored in this browser profile. That is the only copy.": "您的项目存储在此浏览器配置文件中。这是唯一的副本。",
  "Clearing site data deletes them. So does a different browser, or a fresh profile.": "清除站点数据会将其删除。不同的浏览器或新的配置文件也是如此。",
  "Export a project file for anything you want to keep. It carries the design and its media, and it opens on any machine.": "导出您想要保留的任何内容的项目文件。它携带设计及其媒体，并且可以在任何机器上打开。",
