  "Save Profile": "保存个人资料",
  "An account unlocks the online template and asset library, and release news. The editor itself works either way, online or offline.": "账户解锁在线模板和资源库，发布新闻。编辑器本身可以在线或离线工作。",
  "Sign in to unlock:": "登录以解锁：",
  "The online template and asset library": "在线模板和资源库",
  "Release news and early access to new features": "发布新闻并抢先体验新功能",
  "The editor itself works either way, with or without an account, online or offline.": "编辑器本身可以以任何方式工作，无论有或没有帐户，在线或离线。",
  "Create an account": "创建帐户",
  "WHAT THIS APP SENDS": "此应用发送什么内容",
  "Once a day: an install id, the app version, your platform and language, and your account id once you sign in.": "每天一次：安装 ID、应用版本、您的平台和语言以及登录后的帐户 ID。",
  "Nothing about your designs. No document, no title, no file name, no image.": "与您的设计无关。没有文档，没有标题，没有文件名，没有图像。",
  "WHERE THE SESSION IS KEPT": "会话举行地点",
  "You are running the browser build, where every local page shares one storage area, so another local file opened in this browser could read this session. It is therefore short-lived (about 24 hours) and can only read the template library. The desktop app keeps its own isolated storage.": "您正在运行浏览器版本，其中每个本地页面共享一个存储区域，因此在此浏览器中打开的另一个本地文件可以读取此会话。因此它的生命周期很短（大约24小时）并且只能读取模板库。桌面应用程序保留自己的独立存储。",
  "Your own keys for the stock media providers. They fill the Images and Audio search tabs, and the GIFs and Stickers tabs in Items. Every provider below has a free tier.": "您自己的素材提供商密钥。它们填充图像和音频搜索选项卡，以及项目中的 GIF 和贴纸选项卡。以下每个提供商都有免费套餐。",
  "These keys are stored in this browser only, and this build never sends them anywhere except to the provider itself. Anyone with access to this computer or its browser profile can read them, so use a restricted key with the lowest quota you need.": "这些密钥仅存储在该浏览器中，并且此构建不会将它们发送到除提供者本身之外的任何地方。任何有权访问此计算机或其浏览器配置文件的人都可以读取它们，因此请使用具有所需最低配额的受限密钥。",
  "Save keys": "保存密钥",
  "1. Go to unsplash.com/oauth/applications and create an app": "1. 转至 unsplash.com/oauth/applications 并创建一个应用程序",
  "2. Copy the Access Key, not the Secret Key": "2. 复制访问密钥，而不是秘密密钥",
  "Header: Authorization: Client-ID YOUR_KEY - 50 req/hr on demo, 5000 req/hr in production": "标头：授权：客户端 ID YOUR_KEY - 演示中 50 个请求/小时，生产中 5000 个请求/小时",
  "1. Go to pexels.com/api and request a key": "1. 访问 pexels.com/api 并请求密钥",
  "2. It is issued instantly": "2. 立即发出",
  "Header: Authorization: YOUR_KEY - 200 req/hr, 20K req/month": "标头：授权：YOUR_KEY - 200 请求/小时，20K 请求/月",
  "1. Go to pixabay.com/api/docs/ and sign up": "1. 访问 pixabay.com/api/docs/ 并注册",
  "2. Copy the key shown on the docs page": "2. 复制文档页面",
  "500K+ CC-licensed sound effects - header: Authorization: Token YOUR_KEY": "500K+ CC 许可的音效 - 标题：授权：令牌 YOUR_KEY",
  "1. Go to freesound.org/apiv2/apply and create an API app": "1. 转至 freesound.org/apiv2/apply 并创建 API 应用程序",
  "2. Copy the API Token": "2. 复制 API 令牌",
  "1. Go to devportal.jamendo.com and register an app": "1. 转至 devportal.jamendo.com 并注册应用程序",
  "2. Copy the Client ID": "2. 复制客户端 ID",
  "1. Go to developers.giphy.com and create an app": "1. 转至developers.giphy.com 并创建一个应用",
  "2. Copy the API Key": "2. 复制 API 密钥",
