  "In multi-page projects, to keep the app fast, pages you haven't opened for a long time are put to sleep in the background. Their content is safely stored and instantly returns when you click its tab. The page you're working on, a few nearby pages, and video / infinite canvas / slide / board pages always stay open.": "在多页面项目中，为了保持应用程序快速，长时间未打开的页面会在后台进入休眠状态。它们的内容被安全存储，并在您单击其选项卡时立即返回。您正在处理的页面、附近的一些页面以及视频/无限画布/幻灯片/板页面始终保持打开状态。",
